from openpyxl import load_workbook
from openpyxl.styles import Alignment, Font
import math

def round_number(value):
    return round(value, 1) if not isinstance(value, str) else value

def apply_number_format(cell):
    cell.number_format = '#0.0'
    if cell.value is not None and isinstance(cell.value, (int, float)):
        cell.value = round_number(cell.value)
    return cell

def set_formatting(ws):
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=4, max_col=6):
        for cell in row:
            apply_number_format(cell)
            cell.font = Font(bold=True)
            cell.alignment = Alignment(horizontal='center')

def convert_to_values(ws):
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=4, max_col=6):
        for cell in row:
            if isinstance(cell.value, (int, float)):
                cell.value = round_number(cell.value)
            else:
                cell.value = None

def detect_and_sort_blocks(ws):
    rows = []
    current_block = []
    in_block = False

    for i, row in enumerate(ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=1)):
        if not row[0].value:
            if in_block:
                rows.append(current_block)
                current_block = []
                in_block = False
            else:
                pass
        else:
            if not in_block:
                in_block = True
                current_block.append(i + 1)
            else:
                current_block.append(i + 1)

    if in_block:
        rows.append(current_block)

    for block in rows:
        start_row = block[0]
        end_row = block[-1]
        data_rows = list(range(start_row, end_row + 1))

        # Sort the data rows within the block by column D (column 4) in descending order
        sorted_rows = sorted(data_rows, key=lambda r: ws[f'D{r}'].value, reverse=True)

        # Clear the original rows and insert the sorted rows
        for i in range(end_row, start_row - 1, -1):
            ws.delete_rows(i)
        for i, r in enumerate(sorted_rows):
            ws.insert_rows(r)
            # Ensure formulas are converted to values
            for col in range(4, 7):
                cell = ws[chr(64 + col) + str(r)]
                if isinstance(cell.value, (int, float)):
                    cell.value = round_number(cell.value)
                else:
                    cell.value = None

        # Insert one blank row after the block
        if block != rows[-1]:
            ws.insert_rows(end_row + 1)

def main():
    input_path = 'input.xlsx'
    output_path = 'output.xlsx'

    wb = load_workbook(input_path)
    ws = wb['Sheet1']

    # Convert formulas in columns D, E, F to values
    convert_to_values(ws)

    # Apply formatting
    set_formatting(ws)

    # Detect and sort blocks
    detect_and_sort_blocks(ws)

    # Save the workbook
    wb.save(output_path)

if __name__ == '__main__':
    main()
