# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Initialize a dictionary to count occurrences of each number in Column A
count_map = {}

# Iterate through each row in Column A (from row 2 to row 21)
for row in ws.iter_rows(min_row=2, max_row=21, min_col=1, max_col=1):
    item = row[0].value
    if item is not None:
        if item in count_map:
            count_map[item] += 1
        else:
            count_map[item] = 1

# Write the counts into Column B (from row 2 to row 21)
for idx, row in enumerate(ws.iter_rows(min_row=2, max_row=21, min_col=2, max_col=2), start=1):
    item = ws[f"A{idx}"].value
    if item in count_map:
        row[0].value = count_map[item]
    else:
        row[0].value = 0

# Save the modified workbook as output.xlsx
wb.save('output.xlsx')
