for customer, total, country in data:
    if country != 'US':
        if customer not in max_non_us_totals or total > max_non_us_totals[customer]:
            max_non_us_totals[customer] = total

# Write the computed values into the output range
for i, (customer, total, country) in enumerate(data, start=2):
    if country != 'US':
        ws[f'D{i}'] = country
    else:
        ws[f'D{i}'] = max_non_us_totals[customer] if customer in max_non_us_totals else ''

